94	func twoRepoWorkspace(t *testing.T, a, aIntent string, aHeads []string, b, bIntent string, bHeads []string) (EntireEnv, workspace.Manifest) {
95		t.Helper()
96		env := EntireEnv{PluginDataDir: t.TempDir()}
97		aDir, _ := brainDirForKey(env, a)
98		bDir, _ := brainDirForKey(env, b)
99		seedPromotableMember(t, aDir, a, aIntent, aHeads...)
100		seedPromotableMember(t, bDir, b, bIntent, bHeads...)
101		manifest := workspace.Manifest{Name: "plat", Repos: []workspace.Repo{{RepoKey: a}, {RepoKey: b}}}
102		if err := workspaceStore(env).WriteManifest(manifest); err != nil {
103			t.Fatal(err)
104		}
105		if _, err := buildWorkspacePatternCorpus(env, manifest, time.Now()); err != nil {
106			t.Fatal(err)
107		}
108		return env, manifest
109	}
