1	package cli
2	
3	import (
4		"database/sql"
5		"errors"
6		"math"
7		"os"
8		"sort"
9		"strconv"
10		"strings"
11		"time"
12	
13		clibase "github.com/entireio/entire-brain/internal/cli/internal/base"
14		"github.com/entireio/entire-brain/internal/cli/internal/brainstore"
15		"github.com/entireio/entire-brain/internal/cli/internal/sqlitedriver"
16		patterncore "github.com/entireio/entire-brain/internal/cli/patterns"
17		"github.com/entireio/entire-brain/internal/cli/workspace"
18	)
19	
20	// Workspace V2 corpus (Pattern Consolidation v2, Priority 2).
21	//
22	// Cross-repo patterns are aggregated from each member repo's corpus.sqlite (the
23	// already-built V2 analytical index), NOT from the legacy merged JSON files and
24	// NOT by copying raw member episodes between repo stores. A pattern surfaces at
25	// the workspace level only when ≥2 member repos share the same
26	// (type, intent_sig, gram, meta_id) key. The aggregate is written to a workspace
27	// corpus at <workspaceDir>/patterns/corpus.sqlite using the same schema as a repo
28	// corpus (scope='workspace'), so every existing surface — patterns list, get,
29	// brief — works uniformly over it. Only anchor pointers (repo_key + session +
30	// path + line, redacted) are copied into the workspace store; transcripts and
31	// raw evidence stay in the member repos.
32	
33	type workspaceCorpusCounts struct {
34		Members    int      `json:"members"`
35		WithCorpus int      `json:"members_with_corpus"`
36		Patterns   int      `json:"patterns"`
37		Warnings   []string `json:"warnings,omitempty"`
38	}
39	
40	// wsPatternKey identifies a candidate shared across member repos.
41	type wsPatternKey struct {
42		typ, intentSig, gram, metaID string
43	}
44	
45	type wsRepoStat struct {
46		repoKey                      string
47		support, succ, corr, neut    int
48		anchorPath                   string
49		anchorLine                   int
50		anchorSession, anchorOutcome string
51		anchorEpisodeID              string
52	}
53	
54	type wsAgg struct {
55		key                       wsPatternKey
56		title, scope              string
57		support, succ, corr, neut int
58		repos                     map[string]*wsRepoStat
59	}
60	
61	// recoverWorkspacePatternCorpusPublication clears an interrupted publication on
62	// the WORKSPACE brain before any derived-read gate runs.
63	//
64	// Every workspace entry point gates on captureWorkspaceDerivedReadPolicies,
65	// which fails closed while the publication marker survives ("run a locked
66	// pattern refresh to recover"). Recovery is what removes that marker, so if it
67	// only ran inside the gated build, refresh would be blocked by the very state
68	// it exists to repair and the workspace corpus would be permanently stuck. The
69	// repo path gets this ordering for free: buildPatternCorpusLocked recovers
70	// first, under the brain write lock, with no gate ahead of it. Read-only
71	// workspace commands deliberately keep failing closed; only the repair path is
72	// allowed through.
73	func recoverWorkspacePatternCorpusPublication(env EntireEnv, manifest workspace.Manifest) error {
74		wsBrainDir, err := workspaceStore(env).Dir(manifest.Name)
75		if err != nil {
76			return err
77		}
78		return brainstore.WithBrainWriteLock(wsBrainDir, func() error {
79			return patterncore.RecoverCorpusPublicationLocked(wsBrainDir, decodePatternCorpusPublication)
80		})
81	}
82	
83	// buildWorkspacePatternCorpus rebuilds the workspace corpus from member corpora.
84	func buildWorkspacePatternCorpus(env EntireEnv, manifest workspace.Manifest, now time.Time) (workspaceCorpusCounts, error) {
85		if err := recoverWorkspacePatternCorpusPublication(env, manifest); err != nil {
86			return workspaceCorpusCounts{}, err
87		}
88		policies, err := captureWorkspaceDerivedReadPolicies(env, manifest)
89		if err != nil {
90			return workspaceCorpusCounts{}, err
91		}
92		var counts workspaceCorpusCounts
93		err = withLockedRetrievalPrivacyPolicies(policies, func() error {
94			var buildErr error
95			counts, buildErr = buildWorkspacePatternCorpusLocked(env, manifest, now)
96			return buildErr
97		})
98		return counts, err
99	}
100	
101	func buildWorkspacePatternCorpusLocked(env EntireEnv, manifest workspace.Manifest, now time.Time) (workspaceCorpusCounts, error) {
102		var counts workspaceCorpusCounts
103		wsBrainDir, err := workspaceStore(env).Dir(manifest.Name)
104		if err != nil {
105			return counts, err
106		}
107		if err := patterncore.RecoverCorpusPublicationLocked(wsBrainDir, decodePatternCorpusPublication); err != nil {
108			return counts, err
109		}
110		path, cleanup, err := patterncore.PrepareCorpusStaging(wsBrainDir)
111		if err != nil {
112			return counts, err
113		}
114		defer cleanup()
115		db, err := sql.Open(sqlitedriver.Name, path)
116		if err != nil {
117			return counts, err
118		}
119		defer db.Close()
120		for _, p := range []string{"PRAGMA busy_timeout=5000", "PRAGMA foreign_keys=ON"} {
121			if _, err := db.Exec(p); err != nil {
122				return counts, err
123			}
124		}
125		for _, stmt := range patterncore.CorpusSchema {
126			if _, err := db.Exec(stmt); err != nil {
127				return counts, err
128			}
129		}
130	
131		repos := append([]workspace.Repo(nil), manifest.Repos...)
132		sort.Slice(repos, func(i, j int) bool { return repos[i].RepoKey < repos[j].RepoKey })
133		counts.Members = len(repos)
134	
135		aggs := map[wsPatternKey]*wsAgg{}
136		for _, repo := range repos {
137			memberBrainDir, err := brainDirForKey(env, repo.RepoKey)
138			if err != nil {
139				counts.Warnings = append(counts.Warnings, repo.RepoKey+": "+err.Error())
140				continue
141			}
142			mdb, err := patterncore.OpenCorpusReadDB(memberBrainDir)
143			if err != nil {
144				if errors.Is(err, os.ErrNotExist) {
145					// A genuinely absent member corpus degrades gracefully (refresh that repo).
146					counts.Warnings = append(counts.Warnings, repo.RepoKey+": no corpus (run `"+clibase.BrainInvocation(os.LookupEnv, "refresh")+"` there)")
147					continue
148				}
149				return counts, err
150			}
151			counts.WithCorpus++
152			if err := collectMemberPatterns(mdb.DB, repo.RepoKey, aggs); err != nil {
153				counts.Warnings = append(counts.Warnings, repo.RepoKey+": "+err.Error())
154			}
155			mdb.Close()
156		}
157	
158		membershipFP := patterncore.WorkspaceMembershipFingerprint(manifest)
159		membershipChanged := patterncore.CorpusMeta(db, "workspace_families_membership") != membershipFP
160		tx, err := db.Begin()
161		if err != nil {
162			return counts, err
163		}
164		if membershipChanged {
165			if _, err := tx.Exec(`UPDATE deep_dossiers SET status='stale' WHERE pattern_id LIKE 'family:%'`); err != nil {
166				tx.Rollback()
167				return counts, err
168			}
169		}
170		if _, err := tx.Exec(`INSERT INTO meta(key,value) VALUES('workspace_families_membership',?) ON CONFLICT(key) DO UPDATE SET value=excluded.value`, membershipFP); err != nil {
171			tx.Rollback()
172			return counts, err
173		}
174		// Rebuildable: clear all prior workspace corpus content, including the
175		// verifier-cache tables — they have no FK cascade, so stale verdicts must not
176		// survive a rebuild and join onto a newly-rebuilt pattern row sharing the same
177		// stable id (which could even suppress it as 'rejected').
178		// themes has no FK to episodes (not cascaded) and is never populated at
179		// workspace scope, so clear it too — a stray theme row must not persist
180		// across rebuilds, be fetchable via `workspace get theme:…`, or skew run counts.
181		// EXCEPTION: agent-verified workspace families (`family:%` deep_dossiers) are
182		// NOT pattern rows (loadAcceptedWorkspaceFamilies reads them directly, never via
183		// a pattern-id join), so the stale-join hazard above does not apply. They are an
184		// expensive agent result keyed by their own member-evidence fingerprint, so a
185		// deterministic rebuild preserves them while membership remains unchanged.
186		// Membership changes mark them stale; explicit verification re-proposes them
187		// when the member-evidence fingerprint changes.
188		for _, stmt := range []string{`DELETE FROM patterns`, `DELETE FROM episodes`, `DELETE FROM workspace_pattern_repos`, `DELETE FROM dossiers`, `DELETE FROM deep_dossiers WHERE pattern_id NOT LIKE 'family:%'`, `DELETE FROM themes`} {
189			if _, err := tx.Exec(stmt); err != nil {
190				tx.Rollback()
191				return counts, err
192			}
193		}
194		ts := now.UTC().Format(time.RFC3339)
195		memberCount := counts.Members
196		for _, a := range aggs {
197			if len(a.repos) < patterncore.WorkspaceMinRepos {
198				continue // a workspace pattern must be shared across ≥2 repos
199			}
200			if err := writeWorkspacePattern(tx, manifest.Name, a, memberCount, ts); err != nil {
201				tx.Rollback()
202				return counts, err
203			}
204			counts.Patterns++
205		}
206		if err := tx.Commit(); err != nil {
207			return counts, err
208		}
209		// Materialize the explanation graph (workspace_repo edges from the per-repo
210		// breakdown) and record the run, mirroring the repo corpus build.
211		if err := buildSynapses(db, now); err != nil {
212			return counts, err
213		}
214		run, err := patternRunFromStaging(db, now)
215		if err != nil {
216			return counts, err
217		}
218		if err := patterncore.FinalizeCorpusStagingLocked(wsBrainDir, path, db, decodePatternCorpusPublication); err != nil {
219			return counts, err
220		}
221		_ = appendPatternRun(wsBrainDir, run)
222		return counts, nil
223	}
224	
225	// collectMemberPatterns reads one member corpus's patterns + top anchor and folds
226	// them into the cross-repo aggregates.
227	func collectMemberPatterns(mdb *sql.DB, repoKey string, aggs map[wsPatternKey]*wsAgg) error {
228		anchors := memberTopAnchors(mdb)
229		// Skip member patterns a verifier (shallow or deep) explicitly rejected — a
230		// rejected pattern must not re-surface by contributing to a cross-repo
231		// aggregate. (needs_split/low_confidence remain eligible; they are softer.)
232		rows, err := mdb.Query(`
233			SELECT p.id, p.type, COALESCE(p.intent_sig,''), COALESCE(p.gram,''), COALESCE(p.meta_id,''),
234			       p.title, p.support, p.outcome_success, p.outcome_corrected, p.outcome_neutral
235			FROM patterns p
236			LEFT JOIN dossiers d ON d.pattern_id = p.id
237			LEFT JOIN deep_dossiers dd ON dd.pattern_id = p.id
238			WHERE p.scope='repo'
239			  AND COALESCE(d.verdict,'') != 'rejected'
240			  AND COALESCE(dd.verdict,'') != 'rejected'`)
241		if err != nil {
242			return err
243		}
244		defer rows.Close()
245		for rows.Next() {
246			var (
247				id, typ, intentSig, gram, metaID, title string
248				support, succ, corr, neut               int
249			)
250			if err := rows.Scan(&id, &typ, &intentSig, &gram, &metaID, &title, &support, &succ, &corr, &neut); err != nil {
251				return err
252			}
253			key := wsPatternKey{typ, intentSig, gram, metaID}
254			a := aggs[key]
255			if a == nil {
256				a = &wsAgg{key: key, title: title, scope: "workspace", repos: map[string]*wsRepoStat{}}
257				aggs[key] = a
258			}
259			a.support += support
260			a.succ += succ
261			a.corr += corr
262			a.neut += neut
263			st := &wsRepoStat{repoKey: repoKey, support: support, succ: succ, corr: corr, neut: neut}
264			if an, ok := anchors[id]; ok {
265				st.anchorPath, st.anchorLine = an.path, an.line
266				st.anchorSession, st.anchorOutcome, st.anchorEpisodeID = an.session, an.outcome, an.episodeID
267			}
268			a.repos[repoKey] = st
269		}
270		return rows.Err()
271	}
272	
273	type memberAnchor struct {
274		path, session, outcome, episodeID string
275		line                              int
276	}
277	
278	func memberTopAnchors(mdb *sql.DB) map[string]memberAnchor {
279		out := map[string]memberAnchor{}
280		rows, err := mdb.Query(`
281			SELECT pe.pattern_id, pe.source_path, pe.start_line, COALESCE(pe.outcome,''), e.id, e.session_id
282			FROM pattern_evidence pe JOIN episodes e ON e.id=pe.episode_id
283			WHERE pe.rank=0`)
284		if err != nil {
285			return out
286		}
287		defer rows.Close()
288		for rows.Next() {
289			var pid, path, outcome, epID, session string
290			var line int
291			if rows.Scan(&pid, &path, &line, &outcome, &epID, &session) == nil {
292				out[pid] = memberAnchor{path: path, line: line, outcome: outcome, episodeID: epID, session: session}
293			}
294		}
295		return out
296	}
297	
298	// writeWorkspacePattern persists one cross-repo pattern: minimal anchor episodes
299	// (pointers only, redacted), the workspace pattern row, its evidence, and the
300	// per-repo breakdown.
301	func writeWorkspacePattern(tx *sql.Tx, workspace string, a *wsAgg, memberCount int, ts string) error {
302		repoKeys := make([]string, 0, len(a.repos))
303		for k := range a.repos {
304			repoKeys = append(repoKeys, k)
305		}
306		sort.Strings(repoKeys)
307	
308		cluster := "workspace:" + workspace + "\x00" + a.key.typ + "\x00" + a.key.intentSig + "\x00gram:" + a.key.gram + "\x00meta:" + a.key.metaID
309		id := "pattern:" + clibase.HexSHA("workspace\x00"+workspace+"\x00"+cluster)
310		strength := workspaceStrengthV2(a.key.typ, len(a.repos), memberCount, a.support, a.succ, a.corr, a.neut)
311		strength = math.Round(strength*1000) / 1000
312	
313		if _, err := tx.Exec(`INSERT INTO patterns
314			(id, type, scope, repo_key, workspace, cluster_key, title, intent_sig, gram, meta_id, strength, strength_label, support,
315			 n_repos, n_authors, n_branches, outcome_success, outcome_corrected, outcome_neutral, outcome_failed, fingerprint, status, created_at, updated_at)
316			VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)`,
317			id, a.key.typ, "workspace", "", workspace, cluster, clibase.RedactText(a.title), a.key.intentSig, a.key.gram, a.key.metaID,
318			strength, patterncore.StrengthLabelV2(strength), a.support, len(a.repos), 0, 0, a.succ, a.corr, a.neut, 0,
319			clibase.HexSHA(cluster+strconv.Itoa(a.support)), "active", ts, ts); err != nil {
320			return err
321		}
322	
323		rank := 0
324		for _, rk := range repoKeys {
325			st := a.repos[rk]
326			if _, err := tx.Exec(`INSERT OR IGNORE INTO workspace_pattern_repos
327				(pattern_id, repo_key, support, outcome_success, outcome_corrected, outcome_neutral) VALUES (?,?,?,?,?,?)`,
328				id, rk, st.support, st.succ, st.corr, st.neut); err != nil {
329				return err
330			}
331			if st.anchorEpisodeID == "" || st.anchorPath == "" {
332				continue
333			}
334			// Minimal anchor episode (pointer only; redacted). Composite-safe id keeps
335			// member episodes from colliding across repos within the workspace corpus.
336			wsEpID := "wsep:" + clibase.HexSHA(rk+"\x00"+st.anchorEpisodeID)
337			if _, err := tx.Exec(`INSERT OR IGNORE INTO episodes
338				(id, episode_key, repo_key, workspace, session_id, turn_ord, branch, source_path, start_line, end_line, outcome, created_at)
339				VALUES (?,?,?,?,?,?,?,?,?,?,?,?)`,
340				wsEpID, wsEpID, rk, workspace, clibase.RedactText(st.anchorSession), 0, "", clibase.RedactText(st.anchorPath), st.anchorLine, st.anchorLine,
341				nonEmptyOr(st.anchorOutcome, "neutral"), ts); err != nil {
342				return err
343			}
344			if _, err := tx.Exec(`INSERT OR IGNORE INTO pattern_evidence
345				(pattern_id, episode_id, rank, outcome, source_path, start_line, end_line) VALUES (?,?,?,?,?,?,?)`,
346				id, wsEpID, rank, nonEmptyOr(st.anchorOutcome, "neutral"), clibase.RedactText(st.anchorPath), st.anchorLine, st.anchorLine); err != nil {
347				return err
348			}
349			rank++
350		}
351		return nil
352	}
353	
354	func nonEmptyOr(s, fallback string) string {
355		if s == "" {
356			return fallback
357		}
358		return s
359	}
360	
361	// workspaceStrengthV2 rewards repo breadth on top of support and outcome — a
362	// pattern shared by more members of the workspace is stronger.
363	func workspaceStrengthV2(typ string, repos, memberCount, support, succ, corr, neut int) float64 {
364		breadth := repoBreadthScore(repos, memberCount)
365		sup := patterncore.SupportScoreV2(support)
366		out := patterncore.OutcomeScoreV2(support, succ, corr, 0)
367		_ = neut
368		base := 0.40*breadth + 0.35*sup + 0.25*out
369		if typ == "risk" {
370			base = math.Max(base, 0.5) // recorded cross-repo failure is inherently notable
371		}
372		return clibase.Clamp01(base)
373	}
374	
375	// getWorkspaceCorpusRecord resolves a bare workspace-aggregate id (pattern: or
376	// theme:) from the workspace corpus, so the ids `workspace patterns` prints are
377	// directly fetchable via `workspace get <ws> <id>`. Graceful: false when absent.
378	func getWorkspaceCorpusRecord(env EntireEnv, workspaceName, id string) (unifiedResult, bool) {
379		result, ok, _ := getWorkspaceCorpusRecordChecked(env, workspaceName, id)
380		return result, ok
381	}
382	
383	func getWorkspaceCorpusRecordChecked(env EntireEnv, workspaceName, id string) (unifiedResult, bool, error) {
384		wsBrainDir, err := workspaceStore(env).Dir(workspaceName)
385		if err != nil {
386			return unifiedResult{}, false, err
387		}
388		switch {
389		case strings.HasPrefix(id, "pattern:"):
390			return getWorkspacePatternChecked(wsBrainDir, id)
391		case strings.HasPrefix(id, "theme:"):
392			return getCorpusThemeChecked(wsBrainDir, id)
393		default:
394			return unifiedResult{}, false, nil
395		}
396	}
397	
398	// getWorkspacePattern renders a workspace-scope aggregate pattern (with its
399	// per-repo breakdown) as a unifiedResult.
400	func getWorkspacePattern(wsBrainDir, patternID string) (unifiedResult, bool) {
401		result, ok, _ := getWorkspacePatternChecked(wsBrainDir, patternID)
402		return result, ok
403	}
404	
405	func getWorkspacePatternChecked(wsBrainDir, patternID string) (unifiedResult, bool, error) {
406		db, present, err := patterncore.OpenCorpusReadDBIfPresent(wsBrainDir)
407		if err != nil {
408			return unifiedResult{}, false, err
409		}
410		if !present {
411			return unifiedResult{}, false, nil
412		}
413		defer db.Close()
414		var typ, title, intentSig, gram, metaID string
415		var strength float64
416		var nRepos int
417		err = db.QueryRow(`SELECT type, title, COALESCE(intent_sig,''), COALESCE(gram,''), COALESCE(meta_id,''), strength, n_repos
418			FROM patterns WHERE id=? AND scope='workspace'`, patternID).Scan(&typ, &title, &intentSig, &gram, &metaID, &strength, &nRepos)
419		if err != nil {
420			if err == sql.ErrNoRows {
421				return unifiedResult{}, false, nil
422			}
423			return unifiedResult{}, false, err
424		}
425		var b strings.Builder
426		b.WriteString(clibase.RedactText(title) + "\n")
427		b.WriteString("workspace " + typ + " across " + strconv.Itoa(nRepos) + " repo(s); strength " +
428			strconv.FormatFloat(strength, 'g', -1, 64) + "\n")
429		rows, err := db.Query(`SELECT repo_key, support FROM workspace_pattern_repos WHERE pattern_id=? ORDER BY repo_key`, patternID)
430		if err == nil {
431			for rows.Next() {
432				var rk string
433				var support int
434				if rows.Scan(&rk, &support) == nil {
435					b.WriteString("  " + clibase.RedactText(rk) + " (" + strconv.Itoa(support) + ")\n")
436				}
437			}
438			rows.Close()
439		}
440		return unifiedResult{Source: "workspace_pattern", ID: patternID, Text: clibase.RedactText(strings.TrimRight(b.String(), "\n"))}, true, nil
441	}
442	
443	// loadWorkspaceRepoBreakdown returns the per-repo breakdown for workspace
444	// patterns, keyed by pattern id.
445	func loadWorkspaceRepoBreakdown(db *sql.DB) map[string][]patternRepoStat {
446		breakdown, _ := loadWorkspaceRepoBreakdownChecked(db)
447		return breakdown
448	}
449	
450	func loadWorkspaceRepoBreakdownChecked(db *sql.DB) (map[string][]patternRepoStat, error) {
451		out := map[string][]patternRepoStat{}
452		rows, err := db.Query(`SELECT pattern_id, repo_key, support, outcome_success, outcome_corrected, outcome_neutral
453			FROM workspace_pattern_repos ORDER BY repo_key`)
454		if err != nil {
455			return nil, err
456		}
457		defer rows.Close()
458		for rows.Next() {
459			var pid, rk string
460			var support, succ, corr, neut int
461			if err := rows.Scan(&pid, &rk, &support, &succ, &corr, &neut); err != nil {
462				return nil, err
463			}
464			out[pid] = append(out[pid], patternRepoStat{
465				RepoKey: rk, Support: support,
466				Reinforcement: reinforcementCounts{Success: succ, Corrected: corr, Neutral: neut},
467			})
468		}
469		return out, rows.Err()
470	}
