1	package cli
2	
3	import (
4		"context"
5		"database/sql"
6		"fmt"
7		"os"
8		"strings"
9		"time"
10	
11		"github.com/entireio/entire-brain/internal/cli/internal/base"
12		patterncore "github.com/entireio/entire-brain/internal/cli/patterns"
13		"github.com/entireio/entire-brain/internal/cli/workspace"
14	)
15	
16	// Workspace semantic merge (SR5).
17	//
18	// Exact (type,intent_sig,gram,meta_id) aggregation stays as a cheap signal, but
19	// equivalent cross-repo workflows that differ in command spelling/order never
20	// merge that way, and generic exact matches can survive. SR5 adds an agent
21	// judgment layer: it groups each member repo's promotable task candidates into
22	// cross-repo FAMILIES by semantic trigger + procedure purpose, records what is
23	// common and what varies per repo, and requires an accepted workspace family
24	// dossier before a workspace skill can be formed. Explicit (`workspace patterns
25	// verify`), egress-gated, cached by the member-candidate fingerprint.
26	
27	const workspaceFamilyMaxPerRepo = 15 // cap member candidates handed to the agent per repo
28	
29	const workspaceFamilyProposeSystemPrompt = `You are given task workflows from MULTIPLE repositories in a workspace, grouped per repo (each with its trigger/intent and the actual commands run).
30	
31	Group workflows that share the same TRIGGER and PROCEDURE PURPOSE into cross-repo families — even when the exact commands differ in spelling or order across repos (e.g. "mise deploy" in one repo and "make release" in another are the same release workflow). Judge by MEANING, not by command string.
32	
33	Rules:
34	- A family must span at least 2 distinct repos.
35	- Reject GENERIC workflows that are not repo-specific practice (plain git add/commit/push/status/diff, ls, cat) — those are not families.
36	- Capture what is COMMON (a repo-neutral workflow) and what VARIES per repo (each repo's actual commands).
37	
38	Return EXACTLY one JSON object and nothing else (no prose, no code fences):
39	{
40	  "families": [
41	    {
42	      "title": "<short title>",
43	      "trigger": "<when this applies / Use when>",
44	      "purpose": "<the procedure purpose>",
45	      "common_workflow": ["<repo-neutral step>", ...],
46	      "per_repo": [ {"repo_key": "<repo>", "commands": ["<actual command>", ...]}, ... ],
47	      "verdict": "accepted" | "rejected" | "needs_split" | "low_confidence"
48	    }
49	  ]
50	}
51	Use "accepted" only for a genuine cross-repo family spanning >=2 repos. Do not invent repo keys not provided.`
52	
53	// proposeWorkspaceFamilies runs the agent judgment layer over member-repo task
54	// candidates and stores accepted cross-repo families as workspace dossiers.
55	func proposeWorkspaceFamilies(ctx context.Context, env EntireEnv, manifest workspace.Manifest, repoDir, agent, model, effort string, run base.DistillAgentRunner, now time.Time) (patterncore.VerifyStats, error) {
56		var stats patterncore.VerifyStats
57		if err := base.RejectAgentForNoEgress(agent); err != nil {
58			return stats, err
59		}
60		wsBrainDir, err := workspaceStore(env).Dir(manifest.Name)
61		if err != nil {
62			return stats, err
63		}
64		err = patterncore.WithCorpusMutationLocked(wsBrainDir, func(db *sql.DB) error {
65			var mutationErr error
66			stats, mutationErr = proposeWorkspaceFamiliesInDB(ctx, db, env, manifest, repoDir, agent, model, effort, run, now)
67			return mutationErr
68		}, decodePatternCorpusPublication)
69		if err != nil {
70			return stats, fmt.Errorf("workspace corpus not built (run `"+base.BrainInvocation(os.LookupEnv, "workspace patterns refresh")+" %s`): %w", manifest.Name, err)
71		}
72		return stats, nil
73	}
74	
75	func proposeWorkspaceFamiliesInDB(ctx context.Context, db *sql.DB, env EntireEnv, manifest workspace.Manifest, repoDir, agent, model, effort string, run base.DistillAgentRunner, now time.Time) (patterncore.VerifyStats, error) {
76		return patterncore.ProposeWorkspaceFamilies(db, manifest, func(repoKey string) ([]map[string]any, error) {
77			memberDir, err := brainDirForKey(env, repoKey)
78			if err != nil {
79				return nil, nil
80			}
81			cands, ok, err := loadCorpusTaskCandidatesChecked(memberDir)
82			if err != nil {
83				return nil, err
84			}
85			if !ok || len(cands) == 0 {
86				return nil, nil
87			}
88			var list []map[string]any
89			for i, c := range cands {
90				if i >= workspaceFamilyMaxPerRepo {
91					break
92				}
93				r := c.Reinforcement
94				list = append(list, map[string]any{
95					"intent": c.IntentSignature, "title": base.RedactText(c.Label), "commands": base.RedactStrings(c.Commands),
96					"support": c.Support, "reinforcement": []int{r.Success, r.Corrected, r.Neutral},
97				})
98			}
99			return list, nil
100		}, func(payload []byte) (string, error) {
101			args, err := base.DistillAgentCommandArgs(agent, nil, workspaceFamilyProposeSystemPrompt)
102			if err != nil {
103				return "", err
104			}
105			args = base.InjectAgentModel(args, agent, model)
106			args = base.InjectAgentEffort(args, agent, effort)
107			out, err := run(ctx, repoDir, args, payload, patterncore.DossierVerifyTimeout)
108			if err != nil {
109				return "", fmt.Errorf("workspace family proposal agent: %w", err)
110			}
111			return out, nil
112		}, now)
113	}
114	
115	// loadAcceptedWorkspaceFamilies returns the accepted cross-repo families.
116	func loadAcceptedWorkspaceFamilies(wsBrainDir string) []patterncore.WorkspaceFamily {
117		families, _ := loadAcceptedWorkspaceFamiliesChecked(wsBrainDir)
118		return families
119	}
120	
121	func loadAcceptedWorkspaceFamiliesChecked(wsBrainDir string) ([]patterncore.WorkspaceFamily, error) {
122		db, present, err := patterncore.OpenCorpusReadDBIfPresent(wsBrainDir)
123		if err != nil {
124			return nil, err
125		}
126		if !present {
127			return nil, nil
128		}
129		defer db.Close()
130		return patterncore.LoadAcceptedWorkspaceFamilies(db.DB, wsBrainDir)
131	}
132	
133	// getAcceptedWorkspaceFamily returns one accepted family by id.
134	func getAcceptedWorkspaceFamily(wsBrainDir, id string) (patterncore.WorkspaceFamily, bool) {
135		family, ok, _ := getAcceptedWorkspaceFamilyChecked(wsBrainDir, id)
136		return family, ok
137	}
138	
139	func getAcceptedWorkspaceFamilyChecked(wsBrainDir, id string) (patterncore.WorkspaceFamily, bool, error) {
140		families, err := loadAcceptedWorkspaceFamiliesChecked(wsBrainDir)
141		if err != nil {
142			return patterncore.WorkspaceFamily{}, false, err
143		}
144		for _, f := range families {
145			if f.ID == id {
146				return f, true, nil
147			}
148		}
149		return patterncore.WorkspaceFamily{}, false, nil
150	}
151	
152	const workspaceFamilySkillSystemPrompt = `You convert a VERIFIED cross-repo workspace family into a SKILL.md for a multi-repo workspace. The family was assembled from real per-repo evidence and accepted by a verifier.
153	
154	The family JSON gives: title, trigger, purpose, common_workflow (repo-neutral steps), and per_repo (each repo's ACTUAL commands). Render it faithfully — do not invent.
155	
156	Rules:
157	- The skill MUST describe what is COMMON across repos AND what VARIES per repo (a per-repo variations section listing each repo's commands).
158	- If the family is plainly generic (git add/commit/push/status), output EXACTLY one line: NOT_A_SKILL: <reason>.
159	
160	Otherwise output ONLY a complete SKILL.md (no fences):
161	- YAML frontmatter: name (lowercase-hyphenated) + description with a concrete "Use when ..." from the trigger.
162	- Body: a Workflow section (the common steps) and a "Per-repo variations" section naming each repo and its commands. Be concise; include only what the family supports.`
163	
164	// synthesizeWorkspaceSkill converts an accepted family into a SKILL.md.
165	func synthesizeWorkspaceSkill(ctx context.Context, repoDir string, f patterncore.WorkspaceFamily, agent, model, effort string, run base.DistillAgentRunner) (skillSynthesisResult, error) {
166		args, err := base.DistillAgentCommandArgs(agent, nil, workspaceFamilySkillSystemPrompt)
167		if err != nil {
168			return skillSynthesisResult{}, err
169		}
170		args = base.InjectAgentModel(args, agent, model)
171		args = base.InjectAgentEffort(args, agent, effort)
172		out, err := run(ctx, repoDir, args, []byte(buildWorkspaceFamilyEvidence(f)), skillSynthesisTimeout)
173		if err != nil {
174			return skillSynthesisResult{}, fmt.Errorf("workspace family synthesis agent: %w", err)
175		}
176		return parseSynthesisOutput(out), nil
177	}
178	
179	func buildWorkspaceFamilyEvidence(f patterncore.WorkspaceFamily) string {
180		var b strings.Builder
181		fmt.Fprintf(&b, "VERIFIED CROSS-REPO WORKSPACE FAMILY (verdict: %s)\n", nonEmptyOr(f.Verdict, "accepted"))
182		fmt.Fprintf(&b, "Title: %s\n", f.Title)
183		fmt.Fprintf(&b, "Trigger / Use when: %s\n", f.Trigger)
184		if f.Purpose != "" {
185			fmt.Fprintf(&b, "Purpose: %s\n", f.Purpose)
186		}
187		if len(f.CommonWorkflow) > 0 {
188			fmt.Fprintf(&b, "Common workflow (repo-neutral):\n")
189			for i, s := range f.CommonWorkflow {
190				fmt.Fprintf(&b, "  %d. %s\n", i+1, s)
191			}
192		}
193		fmt.Fprintf(&b, "Per-repo variations (what differs):\n")
194		for _, v := range f.PerRepo {
195			fmt.Fprintf(&b, "  - %s: %s\n", v.RepoKey, strings.Join(v.Commands, " → "))
196		}
197		return base.RedactText(b.String())
198	}
