15	// memoryStateInventoryMaxEntries bounds every operational directory scan. It
16	// is a variable so adversarial tests can exercise truncation without creating
17	// thousands of files.
18	var memoryStateInventoryMaxEntries = 10_000
19	
20	var (
21		memoryStateLstat    = os.Lstat
22		memoryStateOpenFile = os.OpenFile
23	)
24	
25	// readMemoryStateFile is the single reader for untrusted work-record and abstract state. It binds
26	// the opened descriptor to both lstat observations, rejects aliases and
27	// non-regular files, and reads at most maxBytes. memoryStateReadOpenFlags adds
28	// O_NONBLOCK on Unix so a regular-file-to-FIFO swap cannot hang the worker.
29	func readMemoryStateFile(brainDir, rel, label string, maxBytes int64) ([]byte, bool, error) {
30		return readMemoryStateFileExpected(brainDir, rel, label, maxBytes, nil)
31	}
32	
33	// errMemoryStateEnumerationStale marks the one failure an UNLOCKED scanner may
34	// legitimately see: the file's identity changed between directory enumeration
35	// and open. For a reader holding the Brain write lock that is a genuine
36	// tampering signal. For an unlocked reader it is also the ordinary outcome of a
37	// lock-holding writer's writeFileAtomic rename landing mid-scan.
38	var errMemoryStateEnumerationStale = errors.New("memory state entry changed after directory enumeration")
39	
40	// readMemoryStateFileRefreshed reads a just-enumerated file, tolerating exactly
41	// ONE benign identity change by re-reading against the current identity.
42	//
43	// The unlocked job/hint scanners (memory jobs, the job selectors, the worker
44	// relaunch delay) race the worker's own transitionMemoryJob -> writeFileAtomic
45	// rename. Treating that fresh inode as corruption reported memory_state_unsafe
46	// for a perfectly healthy file, which aborted whole --session-ref commands and
47	// silently dropped runnable jobs from relaunch scheduling. The retry drops only
48	// the enumeration binding: every path-safety, regular-file, descriptor-identity,
49	// and open-alias check still applies, which is the strongest promise an unlocked
50	// reader can honestly make. A second mismatch propagates.
51	func readMemoryStateFileRefreshed(brainDir, rel, label string, maxBytes int64, expected os.FileInfo) ([]byte, bool, error) {
52		data, present, err := readMemoryStateFileExpected(brainDir, rel, label, maxBytes, expected)
53		if err != nil && errors.Is(err, errMemoryStateEnumerationStale) {
54			return readMemoryStateFileExpected(brainDir, rel, label, maxBytes, nil)
55		}
56		return data, present, err
57	}
