59	func readMemoryStateFileExpected(brainDir, rel, label string, maxBytes int64, expected os.FileInfo) ([]byte, bool, error) {
60		f, present, err := openMemoryStateFileExpected(brainDir, rel, label, expected)
61		if err != nil || !present {
62			return nil, present, err
63		}
64		defer f.Close()
65		data, err := base.SafeReadAll(f, maxBytes, filepath.Join(brainDir, rel))
66		if err != nil {
67			return nil, true, fmt.Errorf("%s: read %s %s: %w", brainstore.StateCorruptCode, label, filepath.ToSlash(rel), err)
68		}
69		return data, true, nil
70	}
