	value := reflect.ValueOf(out)
	if value.Kind() != reflect.Pointer || value.IsNil() {
		return fmt.Errorf("decode target must be a non-nil pointer, got %T", out)
	}
	value.Elem().Set(reflect.Zero(value.Elem().Type()))
