import subprocess, re
renames={
 'decodeVersionedJSONBody':'DecodeVersionedJSONBody',
 'decodeStrictVersionedJSON':'DecodeStrictVersionedJSON',
 'isUnknownFieldError':'IsUnknownFieldError',
 'errTrailingJSONData':'ErrTrailingJSONData',
 'memoryErrUnsupportedVersion':'UnsupportedVersionCode',
 'brainstore.StateCorruptCode':'StateCorruptCode',
 'privacyTransactionRel':'PrivacyTransactionRel',
 'historyDirName':'HistoryDirName',
}
def norm(s, apply_renames):
    if apply_renames:
        for a,b in renames.items(): s=s.replace(a,b)
    s=re.sub(r'\bbrainstore\.','',s)
    s=re.sub(r'\s+',' ',s)
    return s
def funcs(src):
    out={}
    for m in re.finditer(r'(?m)^func (Test\w+)\(t \*testing\.T\) \{', src):
        name=m.group(1); i=m.start(); j=src.index('\n}\n', i)
        out[name]=src[i:j]
    return out
old={}
for f in ['internal/cli/versioned_state_test.go','internal/cli/session_privacy_path_safety_test.go']:
    src=subprocess.run(['git','show','HEAD:'+f],capture_output=True,text=True).stdout
    old.update(funcs(src))
new={}
for f in ['internal/cli/internal/brainstore/versioned_state_test.go','internal/cli/internal/brainstore/privacy_transaction_test.go']:
    new.update(funcs(open(f).read()))
import difflib
for name,body in new.items():
    o=norm(old[name],True); n=norm(body,False)
    if o==n: print(name,'IDENTICAL')
    else:
        print(name,'DIFFERS:')
        for d in difflib.unified_diff(o.split(' '), n.split(' '), lineterm='', n=1):
            if d.startswith(('+','-')) and not d.startswith(('+++','---')): print('  ',d)
EOF

