54	type patternCorpusPublicationReadState string
55	
56	const (
57		patternCorpusPublicationCorrupt     patternCorpusPublicationReadState = "corrupt"
58		patternCorpusPublicationUnsafe      patternCorpusPublicationReadState = "unsafe"
59		patternCorpusPublicationUnsupported patternCorpusPublicationReadState = "unsupported"
60	)
61	
62	// patternCorpusPublicationLoadError keeps publication-marker failures
63	// machine-classifiable at privacy inventory and deletion boundaries. In
64	// particular, a newer producer's marker is unsupported read-only state, not a
65	// disposable corrupt leaf.
66	type patternCorpusPublicationLoadError struct {
67		Code    string
68		State   patternCorpusPublicationReadState
69		Version int
70		Err     error
71	}
72	
73	func (e *patternCorpusPublicationLoadError) Error() string {
74		detail := "pattern corpus publication marker is invalid"
75		if e.Err != nil {
76			detail = e.Err.Error()
77		}
78		if strings.HasPrefix(detail, e.Code+":") {
79			return detail
80		}
81		return e.Code + ": " + detail
82	}
83	
84	func (e *patternCorpusPublicationLoadError) Unwrap() error { return e.Err }
85	
86	func newPatternCorpusPublicationLoadError(err error, version int) error {
87		code := brainstore.MemoryErrorCode(err)
88		state := patternCorpusPublicationCorrupt
89		switch code {
90		case brainstore.UnsupportedVersionCode:
91			state = patternCorpusPublicationUnsupported
92		case brainstore.StateUnsafeCode:
93			state = patternCorpusPublicationUnsafe
94		default:
95			code = brainstore.StateCorruptCode
96		}
97		return &patternCorpusPublicationLoadError{Code: code, State: state, Version: version, Err: err}
98	}
99	
100	// decodePatternCorpusPublication is the single classifier for publication
101	// markers at both recovery and privacy-cleanup boundaries. It classifies the
102	// version header before a strict current-schema decode so a future producer's
103	// additional fields remain opaque, read-only state.
104	func decodePatternCorpusPublication(data []byte) (patterncore.CorpusPublication, error) {
105		var publication patterncore.CorpusPublication
106		version, err := brainstore.DecodeStrictVersionedJSON(data, &publication, patterncore.CorpusPublicationVersion, "pattern corpus publication marker")
107		if err != nil {
108			return patterncore.CorpusPublication{}, newPatternCorpusPublicationLoadError(err, version)
109		}
110		decodedSHA, decodeErr := hex.DecodeString(publication.SHA256)
111		if publication.SchemaVersion != patterncore.CorpusPublicationVersion ||
112			!strings.HasPrefix(publication.Candidate, patterncore.CorpusStagingPrefix) ||
113			filepath.Base(publication.Candidate) != publication.Candidate ||
114			strings.ContainsAny(publication.Candidate, `/\`) ||
115			decodeErr != nil || len(decodedSHA) != sha256.Size || publication.SHA256 != strings.ToLower(publication.SHA256) ||
116			publication.Size < 1 || publication.Size > brainstore.PrivacySQLiteSnapshotMaxBytes {
117			return patterncore.CorpusPublication{}, newPatternCorpusPublicationLoadError(
118				fmt.Errorf("%s: invalid pattern corpus publication marker", brainstore.StateCorruptCode), publication.SchemaVersion)
119		}
120		return publication, nil
121	}
122	
123	// loadPatternCorpusPublicationForPrivacy binds the parsed marker bytes to the
124	// exact regular-file identity observed by inventory. Callers may retain info
125	// only while holding the Brain privacy/write locks; removal rechecks it.
126	func loadPatternCorpusPublicationForPrivacy(brainDir string) (patterncore.CorpusPublication, os.FileInfo, bool, error) {
127		info, present, err := brainstore.PrivacyArtifactInfo(brainDir, patterncore.CorpusPublicationMarkerPath, "pattern corpus publication marker")
128		if err != nil {
129			return patterncore.CorpusPublication{}, nil, present, newPatternCorpusPublicationLoadError(err, 0)
130		}
131		if !present {
132			return patterncore.CorpusPublication{}, nil, false, nil
133		}
134		if info.Size() < 1 || info.Size() > patterncore.CorpusPublicationMarkerMax {
135			return patterncore.CorpusPublication{}, nil, true, newPatternCorpusPublicationLoadError(
136				fmt.Errorf("%s: pattern corpus publication marker is outside its safe size bounds", brainstore.StateUnsafeCode), 0)
137		}
138		data, stillPresent, err := brainstore.ReadMemoryStateFileExpected(
139			brainDir, patterncore.CorpusPublicationMarkerPath, "pattern corpus publication marker", patterncore.CorpusPublicationMarkerMax, info)
140		if err != nil {
141			return patterncore.CorpusPublication{}, nil, true, newPatternCorpusPublicationLoadError(err, 0)
142		}
143		if !stillPresent {
144			return patterncore.CorpusPublication{}, nil, true, newPatternCorpusPublicationLoadError(
145				fmt.Errorf("%s: pattern corpus publication marker disappeared during inventory", brainstore.StateUnsafeCode), 0)
146		}
147		publication, err := decodePatternCorpusPublication(data)
148		if err != nil {
149			return patterncore.CorpusPublication{}, nil, true, err
150		}
151		return publication, info, true, nil
152	}
