154	// removePatternCorpusPublicationForPrivacy removes only a supported current
155	// marker and only the exact identity whose bytes were classified. Unknown,
156	// corrupt, raced, or unsafe state remains byte-for-byte untouched.
157	func removePatternCorpusPublicationForPrivacy(brainDir string) error {
158		_, info, present, err := loadPatternCorpusPublicationForPrivacy(brainDir)
