23		}
24		if len(stones.Excluded) == 0 {
25			return true, nil
26		}
27		return verifyClean(brainDir)
28	}
29	
30	// VerifyDerivedClean is the full derived-projection verifier. A nil verifier
31	// fails closed: when tombstones exist and no verifier was supplied, derived
32	// reads are refused rather than assumed clean.
33	type VerifyDerivedClean func(brainDir string) (bool, error)
34	
35	func gateVerifier(verify VerifyDerivedClean) func(string) (bool, error) {
36		if verify != nil {
37			return func(brainDir string) (bool, error) { return verify(brainDir) }
38		}
39		return func(string) (bool, error) {
40			return false, fmt.Errorf("%s: derived-projection verifier unavailable; excluded-session cleanup cannot be proven clean", brainstore.PrivacyDirtyCode)
41		}
42	}
43	
44	// RequireDerivedRead fails unless the derived-read gate allows reads.
45	func RequireDerivedRead(brainDir string, verify VerifyDerivedClean) error {
46		allowed, err := DerivedReadGate(brainDir, gateVerifier(verify))
47		if err != nil {
48			return err
49		}
50		if !allowed {
51			return fmt.Errorf("%s: derived pattern state is unavailable until excluded-session cleanup verifies clean; run `"+base.BrainInvocation(os.LookupEnv, "privacy purge")+" <session-id>`", brainstore.PrivacyDirtyCode)
52		}
53		return nil
54	}
55	
56	// CaptureWorkspaceRetrievalPrivacyPolicies captures each member Brain's checked
57	// tombstone identity, deduplicated by repo key.
58	func CaptureWorkspaceRetrievalPrivacyPolicies(env base.EntireEnv, manifest workspace.Manifest) ([]brainstore.RetrievalPrivacyPolicy, map[string]string, error) {
59		policies := make([]brainstore.RetrievalPrivacyPolicy, 0, len(manifest.Repos))
60		byRepo := make(map[string]string, len(manifest.Repos))
61		for _, repo := range manifest.Repos {
62			if _, exists := byRepo[repo.RepoKey]; exists {
63				continue
64			}
65			brainDir, err := base.BrainDirForKey(env, repo.RepoKey)
66			if err != nil {
67				return nil, nil, err
68			}
69			policy, err := brainstore.CaptureRetrievalPrivacyPolicy(brainDir)
70			if err != nil {
71				return nil, nil, err
72			}
73			policies = append(policies, policy)
74			byRepo[repo.RepoKey] = policy.Identity
75		}
76		return policies, byRepo, nil
77	}
78	
79	// CaptureWorkspaceDerivedReadPolicies additionally proves every member's
80	// transcript-derived projections are clean before a workspace aggregate is
81	// read. Policy capture alone only proves the tombstone file did not change; it
82	// cannot make a corpus built before an already-present tombstone safe.
83	func CaptureWorkspaceDerivedReadPolicies(env base.EntireEnv, manifest workspace.Manifest, verify VerifyDerivedClean) ([]brainstore.RetrievalPrivacyPolicy, error) {
84		policies, _, err := CaptureWorkspaceRetrievalPrivacyPolicies(env, manifest)
85		if err != nil {
86			return nil, err
87		}
88		for i := range policies {
89			policy := &policies[i]
90			policy.RequireDerivedClean = true
91			allowed, gateErr := DerivedReadGate(policy.BrainDir, gateVerifier(verify))
92			if gateErr != nil {
93				return nil, gateErr
94			}
95			if !allowed {
96				return nil, fmt.Errorf("%s: workspace member has unverified transcript-derived projections: %s", brainstore.PrivacyDirtyCode, policy.BrainDir)
97			}
98		}
99		// Workspace pattern/theme/family rows live in their own aggregate corpus.
100		// Give that Brain the same final-emission proof as every member so a corpus
101		// alias or replacement after assembly cannot be collapsed into empty output.
102		wsDir, err := workspace.DefaultStore(env).Dir(manifest.Name)
103		if err != nil {
104			return nil, err
105		}
106		wsPolicy, err := brainstore.CaptureRetrievalPrivacyPolicy(wsDir)
107		if err != nil {
108			return nil, err
109		}
110		wsPolicy.RequireDerivedClean = true
111		if err := RequireDerivedRead(wsDir, verify); err != nil {
112			return nil, err
113		}
114		policies = append(policies, wsPolicy)
115		return policies, nil
116	}

