57	// RemoveBrainRelativeFileExpected removes a file only when it is still the
58	// exact inode/file identity observed by a descriptor-bound inventory. Privacy
59	// cleanup uses this after validating content so a raced replacement is never
60	// unlinked under the authority of the original file.
61	func RemoveBrainRelativeFileExpected(brainDir, rel string, expected os.FileInfo) error {
62		if expected == nil {
63			return fmt.Errorf("memory_state_unsafe: missing expected file identity for %s", rel)
64		}
65		if err := clibase.RejectSymlinkedBrainRoot(brainDir); err != nil {
66			return err
67		}
68		clean, err := clibase.CleanBrainRelativePath(rel)
69		if err != nil {
70			return err
71		}
72		if err := clibase.RejectExistingSymlinkPathComponents(brainDir, clean); err != nil {
73			return err
74		}
75		path := filepath.Join(brainDir, clean)
76		current, err := MemoryStateLstat(path)
77		if err != nil {
78			if os.IsNotExist(err) {
79				return fmt.Errorf("memory_state_unsafe: expected file disappeared before removal: %s", filepath.ToSlash(clean))
80			}
81			return err
82		}
83		if current.Mode()&os.ModeSymlink != 0 || !current.Mode().IsRegular() || !os.SameFile(expected, current) {
84			return fmt.Errorf("memory_state_unsafe: file changed before removal: %s", filepath.ToSlash(clean))
85		}
86		if err := os.Remove(path); err != nil {
87			return err
88		}
89		return nil
90	}

